  if (!value || value.schema !== NATIVE_SCHEMA || !Array.isArray(value.files) || !expected ||
      value.files.length !== expected.length || value.files.some((file,index)=>
        file?.name !== expected[index] || !Number.isSafeInteger(file.bytes) ||
