def execute(args, ws):
    name = args.command
    if name in {"init", "state"}:
        return ws.state()
    if name == "catalogue":
        return ws.catalogue()
    if name == "auth-profiles":
        return ws.auth_profiles()
    if name == "connection-save":
        return ws.save_connection(read_json(args.file))
    if name == "connection":
        return ws.connection(args.id)
    if name == "discover":
        return ws.discover(args.connection)
    if name == "discovery":
        return ws.discovery(args.id)
    if name == "groups":
        return ws.groups(args.connection, args.url)
    if name == "group-page":
        return ws.group_page(args.id)
    if name == "export-save":
        return ws.save_export(read_json(args.file))
    if name == "export":
        return ws.export_plan(args.id)
    if name in {"advance", "run"}:
        if name == "run":
            if not 0 <= args.max_wait_seconds <= 7 * 86400:
                raise InputError("Choose a continuation window from 0 to 604800 seconds")
            return run_export(ws, args.export, args.operation, args.max_wait_seconds)
        return ws.advance(args.export, args.operation)
    if name == "operation":
        return ws.operation(args.id)
    if name == "adopt-status":
        return ws.adopt_status(args.operation, {"statusUrl": args.status_url, "reason": args.reason})
    if name == "receive-capture":
        return ws.receive_capture(args.operation, {"sourceId": args.source, "reason": args.reason})
    if name == "cancel":
        return ws.cancel(args.operation, args.request_id)
    if name == "source-add":
        with input_file(args.file, original_workspace.MAX_SOURCE) as stream:
            return ws.add_source(stream, args.label, args.name or Path(args.file).name)
    if name == "source":
        return ws.source(args.id)
    if name == "source-members":
        return ws.source_members(args.id)
    if name == "source-rows":
        return ws.source_rows(args.id, args.resource_type, args.kind, args.offset, args.limit, args.query)
    if name == "source-row":
        return ws.source_row(args.id, args.file_id, args.line)
    if name == "source-packet":
        with ws.source_path(args.id).open("rb") as stream:
            return output_file(args.out, stream)
    if name == "source-member":
        with ws.open_source_member(args.id, args.name) as stream:
            return output_file(args.out, stream)
    if name == "mapping":
        return ws.default_mapping(args.source, args.resource_type, args.name)
    if name == "preview":
        return ws.projection_preview(args.source, read_json(args.plan_file), args.limit)
    if name == "plan-save":
        return ws.save_plan(read_json(args.file))
    if name == "plan":
        return {"id": args.id, "plan": ws.plan(args.id)}
    if name == "build":
        return ws.build(args.source, args.plan)
    if name == "build-review":
        return ws.build_view(args.id)
    if name == "query":
        return ws.query(args.build, read_json(args.params_file) if args.params_file else {})
    if name == "compare":
        return ws.compare(args.before, args.after)
    if name == "changes":
        return ws.comparison_page(args.id, args.offset, args.limit)
    if name == "changes-export":
        with ws.comparison_file(args.id).open("rb") as stream:
            return output_file(args.out, stream)
    if name == "compose":
        return ws.compose(read_json(args.file))
    if name == "dataset-export":
        return ws.export_dataset(args.build, absolute(args.out, "Output"))
    if name == "packet-export":
        return ws.export_packet(args.build, absolute(args.out, "Output"))
    if name == "packet-import":
        with input_file(args.file):
            return ws.import_packet(absolute(args.file, "Input"))
    if name == "workspace-export":
        return ws.export_workspace(absolute(args.out, "Output"))
    if name == "workspace-import":
        with input_file(args.file):
            return ws.import_workspace(absolute(args.file, "Input"))
    if name == "serve":
        if not 0 <= args.port <= 65535:
            raise InputError("Choose a loopback port from 0 to 65535")
        from fhir_server import OperatorServer
        with OperatorServer(ws, args.port) as server:
            emit(server.startup())
            try:
                server.serve_forever(poll_interval=0.2)
            except KeyboardInterrupt:
                pass
        return None
    raise InputError("Unknown FHIR Bulk Data command")


def main(argv=None):
    p = parser()
    args = p.parse_args(argv)
    if not getattr(args, "workspace", None):
        p.error("--workspace is required")
    try:
        path = absolute(args.workspace, "Workspace")
        expected_workspace_id = getattr(args, "expected_workspace_id", None)
        if expected_workspace_id and not path.exists():
            raise InputError("The selected initialized FHIR workspace is no longer present")
        create = args.command in {"init", "serve", "workspace-import", "packet-import"} and not path.exists()
        credentials = getattr(args, "credentials_file", None)
        if credentials:
            credentials = absolute(credentials, "Credentials")
        with Workspace(path, create=create, credentials_file=credentials) as ws:
            if expected_workspace_id is not None and ws.workspace_id != expected_workspace_id:
                raise InputError("The original FHIR workspace differs from the selected workspace UUID")
            result = execute(args, ws)
        if result is not None:
            emit(result)
        if args.command in {"run", "advance"} and result["state"] != "complete":
            return 75
        return 0
    except KeyboardInterrupt:
        emit({"error": "Interrupted; reopen the same retained operation ID to continue"}, sys.stderr)
        return 130
    except (InputError, OSError, ValueError) as exc:
        error = {"error": str(exc), "kind": exc.__class__.__name__}
        for attribute, key in [("provider_status", "providerStatus"), ("retry_after", "retryAfter"),
                               ("not_before", "notBefore"), ("receipt", "receipt")]:
            value = getattr(exc, attribute, None)
            if value is not None:
                error[key] = value
        emit(error, sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

// MIT. FHIR Bulk Data edition selections through the ORIGINAL SF88 buyer and receiving flow.
import { constants } from 'node:fs';
import { open, link, rm, mkdir, lstat } from 'node:fs/promises';
import { createHash, randomUUID } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { readFhirBulkMerchant } from './merchant.mjs';
import { readDatasetBuyerOffer, prepareDatasetBuyer } from '../dataset-refresh/buyer-handoff.mjs';

const fault = (code, message, status = 400) => Object.assign(new Error(message), { code, status });
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function queryString(query) {
  if (!object(query) || Object.entries(query).some(([key, value]) =>
      typeof value !== 'string' || ['snapshot', 'cursor'].includes(key)))
    throw fault('FHIR_BULK_BUYER_QUERY_INVALID', 'Supply original first-page string query parameters; the selected edition supplies snapshot.');
  const value = new URLSearchParams(Object.entries(query)).toString();
  if (value.length > 8192) throw fault('FHIR_BULK_BUYER_QUERY_INVALID', 'The query exceeds the native buyer limit.');
  return value;
}
export async function reviewFhirBulkBuyer({ directory, seller, query = {} } = {}) {
  const release = await readFhirBulkMerchant(directory);
  const review = await readDatasetBuyerOffer({ seller, resource: release.manifest.resource,
    snapshot: release.manifest.snapshot, query: queryString(query) });
  return { ...review, edition: { release: release.manifest.id, family: release.manifest.family,
    snapshot: release.manifest.snapshot } };
}
async function saveExact(path, bytes) {
  const directory = dirname(path);
  await mkdir(directory, { recursive: true, mode: 0o700 });
  const info = await lstat(directory);
  if (!info.isDirectory() || info.isSymbolicLink())
    throw fault('FHIR_BULK_BUYER_DIRECTORY_INVALID', 'Select an original private buyer directory.');
  const temporary = join(directory, '.fhir-bulk-buyer-' + randomUUID());
  let recovered = false;
  try {
    const handle = await open(temporary, 'wx', 0o600);
    try { await handle.writeFile(bytes); await handle.sync(); } finally { await handle.close(); }
    try { await link(temporary, path); }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      const retained = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
      try {
        const before = await retained.stat({ bigint: true });
        if (!before.isFile() || before.size !== BigInt(bytes.length))
          throw fault('FHIR_BULK_BUYER_CONFIG_CONFLICT', 'The selected output contains a different original buyer configuration.', 409);
        const existing = await retained.readFile();
        const after = await retained.stat({ bigint: true });
        if (!existing.equals(bytes) || before.mtimeNs !== after.mtimeNs || before.ctimeNs !== after.ctimeNs)
          throw fault('FHIR_BULK_BUYER_CONFIG_CONFLICT', 'The selected output contains a different original buyer configuration.', 409);
        recovered = true;
      } finally { await retained.close(); }
    }
    const directoryHandle = await open(directory, constants.O_RDONLY);
    try { await directoryHandle.sync(); } finally { await directoryHandle.close(); }
  } finally { await rm(temporary, { force: true }); }
  return { path, bytes: bytes.length, sha256: digest(bytes), recovered };
}
/** Reload the original live offer immediately before its reviewed preparation.
 * The result is the original SF88 draft. Existing operator setup supplies the
 * account, reservation policy and signer; this bridge never creates a signer. */
export async function prepareFhirBulkBuyer({ directory, seller, query = {}, intentId,
  acceptIndex, offerSha256, destination } = {}) {
  const review = await reviewFhirBulkBuyer({ directory, seller, query });
  const prepared = prepareDatasetBuyer(review, { intentId, acceptIndex, offerSha256 });
  const bytes = Buffer.from(prepared.configText, 'utf8');
  if (digest(bytes) !== prepared.configSha256)
    throw fault('FHIR_BULK_BUYER_CONFIG_CHANGED', 'The original buyer preparation returned inconsistent file identity.', 409);
  if (typeof destination !== 'string' || !destination)
    throw new TypeError('Choose a private output file for the original buyer configuration.');
  const saved = await saveExact(resolve(destination), bytes);
  return { ...prepared, edition: review.edition, saved };
}

const HELP = [
  'FHIR Bulk Data original buyer and receiving',
  'offer --release RELEASE_DIR --seller http://127.0.0.1:PORT [--query JSON_STRING_PARAMETERS]',
  'prepare --release RELEASE_DIR --seller http://127.0.0.1:PORT [--query JSON_STRING_PARAMETERS]',
  '        --intent ID --accept-index INDEX --offer-sha SHA256 --out PRIVATE_BUYER.json',
  '',
  'The following commands use the original SF88 dataset CLI unchanged:',
  'init --session PRIVATE_SESSION --config CONFIG --max-pages N --max-total-atomic AMOUNT',
  '     [--snapshot SHA256] [--max-rows N] [--max-page-bytes N]',
  '     Use --workspace ORIGINAL_OPERATOR_WORKSPACE instead of --config to reuse its account.',
  'status|run|recover --session PRIVATE_SESSION',
  'export|deliver --session PRIVATE_SESSION --out DESTINATION',
  'accounting|finalize --session PRIVATE_SESSION [original SF88 options]',
  '',
  'Each live offer is read from the original seller; preparation pins the selected FHIR Bulk Data snapshot.',
  'run retains original per-page quote review, operator reservation and native buyer execution.',
  'recover reads the original attempt; deliver retains the original dataset data-room files.',
].join('\n') + '\n';
function options(args) {
  const [action, ...tokens] = args;
  const allowed = action === 'offer' ? ['--release', '--seller', '--query']
    : ['--release', '--seller', '--query', '--intent', '--accept-index', '--offer-sha', '--out'];
  const flags = {};
  if (tokens.length % 2) throw new TypeError('Each buyer option requires its value.');
  for (let i = 0; i < tokens.length; i += 2) {
    if (!allowed.includes(tokens[i]) || Object.hasOwn(flags, tokens[i]) ||
        !tokens[i + 1] || tokens[i + 1].startsWith('--'))
      throw new TypeError('Unknown, repeated or missing FHIR Bulk Data buyer option.');
    flags[tokens[i]] = tokens[i + 1];
  }
  const required = name => {
    if (!flags[name]) throw new TypeError(name + ' is required.');
    return flags[name];
  };
  let query;
  try {
    if ((flags['--query'] ?? '{}').length > 8192) throw new Error();
    query = JSON.parse(flags['--query'] ?? '{}');
  } catch { throw fault('FHIR_BULK_BUYER_QUERY_INVALID', 'Use a JSON object of original string query parameters.'); }
  const result = { directory: required('--release'), seller: required('--seller'), query };
  if (action === 'prepare') {
    const index = required('--accept-index');
    if (!/^(0|[1-9][0-9]*)$/.test(index) || !Number.isSafeInteger(Number(index)))
      throw new TypeError('--accept-index must be the displayed zero-based payment alternative.');
    Object.assign(result, { intentId: required('--intent'), acceptIndex: Number(index),
      offerSha256: required('--offer-sha'), destination: required('--out') });
  }
  return { action, input: result };
}
export async function main(args = process.argv.slice(2)) {
  if (!args.length || args.length === 1 && ['help', '--help'].includes(args[0])) {
    process.stdout.write(HELP); return;
  }
  if (['init', 'status', 'run', 'recover', 'export', 'deliver', 'accounting', 'finalize'].includes(args[0]))
    return (await import('../../sf88-operator-buyer-cli/dataset-cli.mjs')).main(args);
  if (!['offer', 'prepare'].includes(args[0])) throw new TypeError(HELP);
  const { action, input } = options(args);
  const report = action === 'offer' ? await reviewFhirBulkBuyer(input) : await prepareFhirBulkBuyer(input);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { process.stderr.write(JSON.stringify({ error: error.code ?? 'FHIR_BULK_BUYER', message: error.message }) + '\n'); process.exitCode = 1; });

